"""lead_contact_deduper: Decide for each inbound lead whether it is a new contact, a duplicate, or needs an update.

Compiled offline from the automation spec (no model available).
"""

LEFT_FIELDS = ["lead_id", "email", "company", "phone"]
RIGHT_FIELDS = ["contact_id", "email", "company", "phone"]


def _num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _require(record, fields, side):
    for name in fields:
        if name not in record:
            raise ValueError(side + " record is missing field " + repr(name))


def _key(value):
    text = "" if value is None else str(value)
    text = text.strip()
    text = text.lower()
    return text


def _status(left, right):
    a, b = left['company'], right['company']
    if not (isinstance(a, str) and isinstance(b, str) and a.strip().casefold() == b.strip().casefold()):
        return 'update_company'
    a, b = left['phone'], right['phone']
    if not (isinstance(a, str) and isinstance(b, str) and a.strip() == b.strip()):
        return 'update_phone'
    return 'duplicate'


def run(left, right):
    for record in right:
        _require(record, RIGHT_FIELDS, "right")
    for record in left:
        _require(record, LEFT_FIELDS, "left")
    index = {}
    for record in right:
        index.setdefault(_key(record['email']), []).append(record)
    results = []
    for record in left:
        k = _key(record['email'])
        matches = index.get(k, []) if k else []
        row = {"left_id": record['lead_id'], "right_id": None, "status": 'create_contact'}
        if len(matches) > 1:
            row["status"] = 'manual_review'
        elif len(matches) == 1:
            row["right_id"] = matches[0]['contact_id']
            row["status"] = _status(record, matches[0])
        results.append(row)
    return results
